import mongoose, { Schema, InferSchemaType } from 'mongoose';

const userSchema = new Schema(
  {
    email: { type: String, required: true, unique: true, lowercase: true, trim: true },
    name: { type: String, required: true, maxlength: 80 },
    role: { type: String, enum: ['user', 'admin'], default: 'user' },
    age: { type: Number, min: 0 }
  },
  { timestamps: true }
);

export type User = InferSchemaType<typeof userSchema>;
export const UserModel = mongoose.models.User || mongoose.model('User', userSchema);

await mongoose.connect(process.env.MONGODB_URI!);

userSchema.pre('save', async function () {
  if (!this.isModified('password')) return;
  this.password = await bcrypt.hash(this.password, 12);
});

// Soft-delete filter applied to every find query
userSchema.pre(/^find/, function () {
  this.where({ deletedAt: null });
});

const postSchema = new Schema({
  title: String,
  author: { type: Schema.Types.ObjectId, ref: 'User', required: true }
});
const Post = mongoose.model('Post', postSchema);

const posts = await Post.find({ published: true })
  .populate({ path: 'author', select: 'name' })
  .sort({ createdAt: -1 })
  .limit(20)
  .lean();

// Embed: bounded, read together
{ _id: 1, name: 'Asha', addresses: [ { type: 'home', city: 'Pune' } ] }

// Reference from child: unbounded
// posts
{ _id: 10, title: 'Hello', commentCount: 1240 }
// comments (index on { postId: 1, createdAt: -1 })
{ _id: 501, postId: 10, text: 'Nice', createdAt: ISODate('2026-01-02') }

// Attribute pattern: one index for many specs
{
  sku: 'TV-55',
  specs: [
    { k: 'size', v: 55 },
    { k: 'panel', v: 'OLED' },
    { k: 'hz', v: 120 }
  ]
}
db.products.createIndex({ 'specs.k': 1, 'specs.v': 1 })

db.orders.find({ status: 'paid' }).sort({ createdAt: -1 }).limit(20)
  .explain('executionStats')

// Healthy result (abridged)
// winningPlan: LIMIT -> FETCH -> IXSCAN { status: 1, createdAt: -1 }
// nReturned: 20, totalKeysExamined: 20, totalDocsExamined: 20

// Revenue per customer for paid orders in 2026, top 5
db.orders.aggregate([
  { $match: { status: 'paid', createdAt: { $gte: ISODate('2026-01-01') } } },
  { $group: { _id: '$customerId', revenue: { $sum: '$total' }, orders: { $sum: 1 } } },
  { $sort: { revenue: -1 } },
  { $limit: 5 },
  { $project: { _id: 0, customerId: '$_id', revenue: 1, orders: 1 } }
])

db.orders.aggregate([
  { $match: { status: 'paid' } },
  { $unwind: '$items' },
  { $group: { _id: '$items.sku', units: { $sum: '$items.qty' } } },
  { $lookup: {
      from: 'products',
      localField: '_id',
      foreignField: 'sku',
      as: 'product',
      pipeline: [{ $project: { name: 1, _id: 0 } }]
  } },
  { $unwind: '$product' },
  { $sort: { units: -1 } }
])

db.products.aggregate([
  { $match: { category: 'shoes', price: { $lte: 200 } } },
  { $facet: {
      results: [{ $sort: { price: 1 } }, { $skip: 0 }, { $limit: 20 }],
      total: [{ $count: 'count' }],
      byBrand: [{ $group: { _id: '$brand', n: { $sum: 1 } } }, { $sort: { n: -1 } }]
  } }
])

