const session = client.startSession();
try {
  await session.withTransaction(async () => {
    const accounts = client.db('bank').collection('accounts');
    const res = await accounts.updateOne(
      { _id: fromId, balance: { $gte: amount } },
      { $inc: { balance: -amount } },
      { session }
    );
    if (res.modifiedCount !== 1) throw new Error('Insufficient funds');
    await accounts.updateOne({ _id: toId }, { $inc: { balance: amount } }, { session });
  }, { readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' } });
} finally {
  await session.endSession();
}

const stream = db.collection('orders').watch(
  [{ $match: { operationType: 'insert' } }],
  { fullDocument: 'updateLookup', resumeAfter: savedToken }
);
for await (const change of stream) {
  await notify(change.fullDocument);
  await saveToken(change._id); // resume token
}

sh.enableSharding('shop')   // not required in recent versions, harmless

// Hashed: even write distribution for a monotonically increasing key
sh.shardCollection('shop.events', { _id: 'hashed' })

// Compound ranged: queries per tenant are targeted
sh.shardCollection('shop.orders', { tenantId: 1, orderId: 1 })

db.products.aggregate([
  { $search: {
      index: 'default',
      compound: {
        must: [{ text: { query: 'runing shoes', path: ['name', 'description'], fuzzy: { maxEdits: 1 } } }],
        filter: [{ range: { path: 'price', lte: 150 } }]
      }
  } },
  { $limit: 10 },
  { $project: { name: 1, price: 1, score: { $meta: 'searchScore' } } }
])

